// Canonical owner: GetBrew/brew-v2 scripts/contract/consumer.mjs.
// Consumer copies are generated by contract:import and pinned in the artifact.
import { spawnSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

export function sha256(bytes) {
  return createHash('sha256').update(bytes).digest('hex')
}

function requireDigest(value, label) {
  if (typeof value !== 'string' || !/^[a-f0-9]{64}$/.test(value)) {
    throw new Error(`${label} must be a SHA256 digest`)
  }
}

function readManifest(bytes, expectedDigest) {
  requireDigest(expectedDigest, 'Expected artifact digest')
  if (sha256(bytes) !== expectedDigest) {
    throw new Error(
      'artifact digest mismatch: the manifest does not match the explicit source pin'
    )
  }
  const manifest = JSON.parse(bytes.toString())
  if (
    manifest.schemaVersion !== 1 ||
    manifest.source?.repository !== 'GetBrew/brew-v2' ||
    !/^[a-f0-9]{40}$/.test(manifest.source?.revision ?? '')
  ) {
    throw new Error('Unsupported contract manifest or source identity')
  }
  const files = manifest.files
  if (
    !files ||
    typeof files !== 'object' ||
    Array.isArray(files) ||
    !files['openapi/public-api-v1.yaml'] ||
    !files['tools/contract-artifact.mjs']
  ) {
    throw new Error('Contract manifest is missing its spec or consumer tool')
  }
  for (const [path, digest] of Object.entries(files)) {
    if (
      path !== 'openapi/public-api-v1.yaml' &&
      path !== 'tools/contract-artifact.mjs' &&
      !/^docs\/snippets\/generated\/[a-z0-9-]+\.mdx$/.test(path)
    ) {
      throw new Error(`unsupported artifact path: ${path}`)
    }
    requireDigest(digest, `Digest for ${path}`)
  }
  return manifest
}

function consumerConfig(root) {
  const name = JSON.parse(
    readFileSync(resolve(root, 'package.json'), 'utf8')
  ).name
  const isDocs = name === '@brew.new/docs-checks'
  if (!isDocs && name !== '@brew.new/sdk' && name !== '@brew.new/cli') {
    throw new Error(`Unknown contract consumer ${name}`)
  }
  return {
    isDocs,
    manifestPath: isDocs
      ? 'api-reference/contract-manifest.json'
      : 'openapi/contract-manifest.json',
    generatedPaths: isDocs
      ? []
      : [
          'src/generated/openapi-types.ts',
          ...(name === '@brew.new/cli' ? ['src/generated/input-keys.ts'] : []),
        ],
    destination(path) {
      if (path === 'tools/contract-artifact.mjs') {
        return 'scripts/contract-artifact.mjs'
      }
      if (path === 'openapi/public-api-v1.yaml') {
        return isDocs ? 'api-reference/openapi-public-v1.yaml' : path
      }
      return isDocs ? path.slice('docs/'.length) : null
    },
  }
}

/** Checks the locally pinned artifact. It does not claim to check server freshness. */
export function checkContract({ root }) {
  const config = consumerConfig(root)
  const pin = JSON.parse(
    readFileSync(resolve(root, 'contract.lock.json'), 'utf8')
  )
  if (pin.schemaVersion !== 1) {
    throw new Error('Unsupported contract pin')
  }
  const manifest = readManifest(
    readFileSync(resolve(root, config.manifestPath)),
    pin.artifactSha256
  )
  if (JSON.stringify(manifest.source) !== JSON.stringify(pin.source)) {
    throw new Error('Contract pin source identity differs from the artifact')
  }
  for (const [path, digest] of Object.entries(manifest.files)) {
    const destination = config.destination(path)
    if (
      destination &&
      sha256(readFileSync(resolve(root, destination))) !== digest
    ) {
      throw new Error(
        `Contract digest mismatch: ${destination}; import the intended artifact instead of editing generated files`
      )
    }
  }
  if (config.isDocs) {
    const managed = new Set(Object.keys(manifest.files).map(config.destination))
    for (const file of readdirSync(resolve(root, 'snippets/generated'))) {
      if (file.endsWith('.mdx') && !managed.has(`snippets/generated/${file}`)) {
        throw new Error(`Unpinned generated snippet: ${file}`)
      }
    }
  }
  return pin
}

/** Validate the entire explicit artifact before updating this checkout. */
export function importContract({ artifact, root, artifactSha256 }) {
  const config = consumerConfig(root)
  const manifestBytes = readFileSync(resolve(artifact, 'manifest.json'))
  const manifest = readManifest(manifestBytes, artifactSha256)
  const payloads = new Map()
  for (const [path, digest] of Object.entries(manifest.files)) {
    const bytes = readFileSync(resolve(artifact, path))
    if (sha256(bytes) !== digest) {
      throw new Error(`Contract digest mismatch: ${path}`)
    }
    const destination = config.destination(path)
    if (destination) {
      payloads.set(destination, bytes)
    }
  }
  const previousManifestPath = resolve(root, config.manifestPath)
  if (existsSync(previousManifestPath)) {
    const previousPin = JSON.parse(
      readFileSync(resolve(root, 'contract.lock.json'), 'utf8')
    )
    const previousManifest = readManifest(
      readFileSync(previousManifestPath),
      previousPin.artifactSha256
    )
    for (const path of Object.keys(previousManifest.files)) {
      const destination = config.destination(path)
      if (destination && !payloads.has(destination)) {
        payloads.set(destination, null)
      }
    }
  }
  const pin = { schemaVersion: 1, artifactSha256, source: manifest.source }
  payloads.set(config.manifestPath, manifestBytes)
  payloads.set(
    'contract.lock.json',
    Buffer.from(`${JSON.stringify(pin, null, 2)}\n`)
  )
  const previous = new Map(
    [...payloads.keys(), ...config.generatedPaths].map((path) => {
      const absolute = resolve(root, path)
      return [path, existsSync(absolute) ? readFileSync(absolute) : null]
    })
  )
  try {
    for (const [path, bytes] of payloads) {
      const absolute = resolve(root, path)
      mkdirSync(dirname(absolute), { recursive: true })
      if (bytes === null) {
        rmSync(absolute, { force: true })
      } else {
        writeFileSync(absolute, bytes)
      }
    }
    if (!config.isDocs) {
      const result = spawnSync(
        process.execPath,
        ['scripts/generate-types.mjs'],
        { cwd: root, stdio: 'inherit' }
      )
      if (result.error || result.status !== 0) {
        throw new Error(
          `Contract type generation failed: ${result.error?.message ?? result.status}`
        )
      }
    }
    checkContract({ root })
  } catch (error) {
    for (const [path, bytes] of previous) {
      const absolute = resolve(root, path)
      if (bytes === null) {
        rmSync(absolute, { force: true })
      } else {
        writeFileSync(absolute, bytes)
      }
    }
    throw error
  }
  return pin
}

if (
  process.argv[1] &&
  resolve(process.argv[1]) === fileURLToPath(import.meta.url)
) {
  try {
    const [command, ...args] = process.argv
      .slice(2)
      .filter((value) => value !== '--')
    const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
    if (command === 'check' && args.length === 0) {
      console.log(JSON.stringify(checkContract({ root })))
    } else if (
      command === 'import' &&
      args.length === 4 &&
      args[0] === '--artifact' &&
      args[2] === '--digest'
    ) {
      console.log(
        JSON.stringify(
          importContract({
            root,
            artifact: resolve(args[1]),
            artifactSha256: args[3],
          })
        )
      )
    } else {
      throw new Error(
        'Usage: contract-artifact.mjs check | import --artifact <directory> --digest <sha256>'
      )
    }
  } catch (error) {
    console.error(error.message)
    process.exitCode = 1
  }
}
